package com.personal.assistant.module.auth.controller;import com.personal.assistant.common.response.ApiResponse;import com.personal.assistant.common.security.*;import com.personal.assistant.module.auth.dto.*;import com.personal.assistant.module.auth.service.AuthService;import com.personal.assistant.module.security.service.SecurityAuditService;import io.swagger.v3.oas.annotations.*;import io.swagger.v3.oas.annotations.tags.Tag;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;
@Tag(name="认证管理",description="登录、退出与当前用户")@RestController @RequestMapping("/api/auth")public class AuthController{private final AuthService auth;private final SecurityAuditService audit;public AuthController(AuthService auth,SecurityAuditService audit){this.auth=auth;this.audit=audit;}@Operation(summary="登录")@PostMapping("/login")public ApiResponse<LoginResponse>login(@Valid @RequestBody LoginRequest r,HttpServletRequest request){return ApiResponse.success(auth.login(r,request));}@GetMapping("/me")public ApiResponse<AuthUser>me(){return ApiResponse.success(SecurityContextHelper.currentUser());}@PostMapping("/change-password")public ApiResponse<Void>change(@Valid @RequestBody ChangePasswordRequest r,HttpServletRequest request){auth.changePassword(SecurityContextHelper.currentUserId(),r,request);return ApiResponse.success();}@PostMapping("/logout")public ApiResponse<Void>logout(HttpServletRequest request){AuthUser user=SecurityContextHelper.currentUser();audit.record(user.userId(),user.username(),"LOGOUT","ACCOUNT",String.valueOf(user.userId()),true,null,request);return ApiResponse.success();}}
